func ptrPermit(p unsafe.Pointer, c int32) any {
	r := (*permit.Permit)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.StateID))
	case 5:
		return &r.PermitNumber
	case 6:
		return (*string)(unsafe.Pointer(&r.Status))
	case 7:
		return &r.IssuedAt
	case 8:
		return &r.ExpiresAt
	case 9:
		return &r.Cost
	case 10:
		return &r.Notes
	case 11:
		return &r.Version
	case 12:
		return &r.CreatedAt
	case 13:
		return &r.UpdatedAt
	case 14:
		return &r.SearchVector
	case 15:
		return &r.Rank
	}
	return nil
}

func valuePermit(p unsafe.Pointer, c int32) any {
	r := (*permit.Permit)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.StateID)
	case 5:
		return r.PermitNumber
	case 6:
		return string(r.Status)
	case 7:
		if r.IssuedAt == nil {
			return nil
		}
		return *r.IssuedAt
	case 8:
		if r.ExpiresAt == nil {
			return nil
		}
		return *r.ExpiresAt
	case 9:
		return r.Cost
	case 10:
		if r.Notes == "" {
			return nil
		}
		return r.Notes
	case 11:
		return r.Version
	case 12:
		return r.CreatedAt
	case 13:
		return r.UpdatedAt
	case 14:
		return r.SearchVector
	case 15:
		return r.Rank
	}
	return nil
}

func attachPermit(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*permit.Permit)(p)
	switch rel {
	case 0:
		r.State = (*usstate.UsState)(child)
	}
}

