func newRequirement() unsafe.Pointer { return unsafe.Pointer(new(permit.Requirement)) }

func newNRequirement(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]permit.Requirement, n)))
}

func ptrRequirement(p unsafe.Pointer, c int32) any {
	r := (*permit.Requirement)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.StateID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return &r.RouteSequence
	case 7:
		return &r.Exceedances
	case 8:
		return &r.Escorts
	case 9:
		return &r.Restrictions
	case 10:
		return &r.LeadTimeDays
	case 11:
		return &r.ValidityDays
	case 12:
		return &r.EstimatedFee
	case 13:
		return &r.IsSuperload
	case 14:
		return (**string)(unsafe.Pointer(&r.SatisfiedByPermitID))
	case 15:
		return (**string)(unsafe.Pointer(&r.WaivedByID))
	case 16:
		return &r.WaiverReason
	case 17:
		return &r.Provenance
	case 18:
		return &r.DerivedAt
	case 19:
		return &r.Version
	case 20:
		return &r.CreatedAt
	case 21:
		return &r.UpdatedAt
	}
	return nil
}

func valueRequirement(p unsafe.Pointer, c int32) any {
	r := (*permit.Requirement)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.StateID)
	case 5:
		return string(r.Status)
	case 6:
		return r.RouteSequence
	case 7:
		if r.Exceedances == nil {
			return nil
		}
		return r.Exceedances
	case 8:
		if r.Escorts == nil {
			return nil
		}
		return r.Escorts
	case 9:
		if r.Restrictions == nil {
			return nil
		}
		return r.Restrictions
	case 10:
		return r.LeadTimeDays
	case 11:
		return r.ValidityDays
	case 12:
		return r.EstimatedFee
	case 13:
		return r.IsSuperload
	case 14:
		if r.SatisfiedByPermitID == nil {
			return nil
		}
		return string(*r.SatisfiedByPermitID)
	case 15:
		if r.WaivedByID == nil {
			return nil
		}
		return string(*r.WaivedByID)
	case 16:
		if r.WaiverReason == "" {
			return nil
		}
		return r.WaiverReason
	case 17:
		if r.Provenance == nil {
			return nil
		}
		return *r.Provenance
	case 18:
		return r.DerivedAt
	case 19:
		return r.Version
	case 20:
		return r.CreatedAt
	case 21:
		return r.UpdatedAt
	}
	return nil
}

func attachRequirement(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*permit.Requirement)(p)
	switch rel {
	case 0:
		r.State = (*usstate.UsState)(child)
	case 1:
		r.SatisfiedByPermit = (*permit.Permit)(child)
	}
}

